"use client";

import { forwardRef } from "react";
import { Label, ProgressBar as AriaProgressBar, type ProgressBarProps as AriaProgressBarProps } from "react-aria-components";
import { progressDefaults, type ProgressSpecProps } from "../generated/progress.types";
import { cx } from "../utils/cx";

export interface ProgressProps
  extends ProgressSpecProps,
    Omit<AriaProgressBarProps, keyof ProgressSpecProps | "className" | "children" | "aria-label" | "valueLabel"> {
  className?: string;
}

const bars: Record<NonNullable<ProgressSpecProps["variant"]>, string> = {
  default: "bg-[var(--rd-color-action-primary)]",
  success: "bg-[var(--rd-color-feedback-success)]",
  warning: "bg-[var(--rd-color-feedback-warning)]",
  danger: "bg-[var(--rd-color-feedback-danger)]",
};
const heights: Record<NonNullable<ProgressSpecProps["size"]>, string> = { sm: "h-1.5", md: "h-2.5" };

export const Progress = forwardRef<HTMLDivElement, ProgressProps>(function Progress(
  {
    label,
    valueLabel,
    variant = progressDefaults.variant,
    size = progressDefaults.size,
    showValue = progressDefaults.showValue,
    isIndeterminate = progressDefaults.isIndeterminate,
    minValue = progressDefaults.minValue,
    maxValue = progressDefaults.maxValue,
    className,
    ...rest
  },
  ref,
) {
  return (
    <AriaProgressBar
      {...rest}
      ref={ref}
      minValue={minValue}
      maxValue={maxValue}
      isIndeterminate={isIndeterminate}
      valueLabel={valueLabel}
      className={cx("flex w-full flex-col gap-1.5 text-sm", className)}
    >
      {({ percentage, valueText }) => (
        <>
          <div className="flex items-baseline justify-between gap-2">
            <Label className="font-medium text-[var(--rd-color-text-default)]">{label}</Label>
            {showValue && !isIndeterminate && (
              <span className="tabular-nums text-[var(--rd-color-text-muted)]">{valueLabel ?? valueText}</span>
            )}
          </div>
          <div className={cx("w-full overflow-hidden rounded-full bg-[var(--rd-color-border-default)]", heights[size])}>
            <div
              className={cx(
                "h-full rounded-full transition-[width] duration-300 motion-reduce:transition-none",
                bars[variant],
                // The amount is unknown: a full, pulsing bar. Reduced motion keeps it still.
                isIndeterminate && "w-full animate-pulse motion-reduce:animate-none",
              )}
              style={isIndeterminate ? undefined : { width: `${percentage}%` }}
            />
          </div>
        </>
      )}
    </AriaProgressBar>
  );
});

// Generated by rdloom codegen from specs/progress.spec.json (v0.1.0).
// Do not edit. Change the spec and run `npm run gen`.

export const progressVariantValues = ["default", "success", "warning", "danger"] as const;
export const progressSizeValues = ["sm", "md"] as const;

/** A bar showing how far along a task is, or that something is working when the amount is unknown. */
export interface ProgressSpecProps {
  /**
   * What is progressing, e.g. 'Uploading report.pdf'. It is the accessible name.
   */
  label: string;
  /**
   * Current value between minValue and maxValue. Leave out with isIndeterminate.
   */
  value?: number;
  /**
   * Value at an empty bar.
   * @default 0
   */
  minValue?: number;
  /**
   * Value at a full bar.
   * @default 100
   */
  maxValue?: number;
  /**
   * The amount is unknown: shows a full, pulsing bar and no number.
   * @default false
   */
  isIndeterminate?: boolean;
  /**
   * Shows the percentage (or valueLabel) beside the label.
   * @default true
   */
  showValue?: boolean;
  /**
   * Replaces the percentage in text and for screen readers, e.g. '3 of 10 files'.
   */
  valueLabel?: string;
  /**
   * Bar color. Say it in the label too: color alone isn't enough.
   * @default "default"
   */
  variant?: "default" | "success" | "warning" | "danger";
  /**
   * Bar thickness.
   * @default "md"
   */
  size?: "sm" | "md";
}

export const progressDefaults = {
  minValue: 0,
  maxValue: 100,
  isIndeterminate: false,
  showValue: true,
  variant: "default",
  size: "md",
} as const;

export const progressMeta = {
  "name": "Progress",
  "version": "0.1.0",
  "status": "experimental",
  "role": "progressbar"
} as const;
